import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const STATUSES = ['기안', '결재대기', '승인', '보류', '반려', '회수', '재기안', '완료'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function text(v: unknown): string {
  if (v === undefined || v === null) {
    return '';
  }
  return String(v).trim();
}

function pathId(v: unknown, label: string): string {
  const s = text(v);
  if (!/^[0-9]{1,18}$/.test(s)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값이 올바르지 않습니다.');
  }
  return s;
}

@Controller('api/v1')
export class FnSfr00403Controller {
  @Get('/approval-items')
  async listApprovalItems(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자', '임직원');
    const q = checks.queryOf(req.query);
    const fromDate = text(q['fromDate']);
    const toDate = text(q['toDate']);
    const projectId = text(q['projectId']);
    const status = text(q['status']);
    const pageText = text(q['page']);
    const sizeText = text(q['size']);
    const page = pageText === '' ? 0 : Number(pageText);
    const size = sizeText === '' ? DEFAULT_SIZE : Number(sizeText);
    if (!Number.isInteger(page) || page < 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호가 올바르지 않습니다.');
    }
    if (!Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 크기가 올바르지 않습니다.');
    }
    const limit = Math.min(size, MAX_SIZE);
    const datePattern = /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/;
    if (fromDate !== '' && !datePattern.test(fromDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 시작일 형식이 올바르지 않습니다.');
    }
    if (toDate !== '' && !datePattern.test(toDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 종료일 형식이 올바르지 않습니다.');
    }
    if (projectId !== '' && !/^[0-9]{1,18}$/.test(projectId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '프로젝트 값이 올바르지 않습니다.');
    }
    if (status !== '' && !STATUSES.includes(status)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '진행 상태 값이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const conds: string[] = [];
      const params: Record<string, unknown> = {};
      if (fromDate !== '') {
        conds.push('er.created_at >= CAST(:fromDate AS date)');
        params['fromDate'] = fromDate;
      }
      if (toDate !== '') {
        conds.push('er.created_at < CAST(:toDate AS date) + 1');
        params['toDate'] = toDate;
      }
      if (projectId !== '') {
        conds.push('er.project_id = CAST(:projectId AS bigint)');
        params['projectId'] = projectId;
      }
      if (status !== '') {
        conds.push('er.status = :status');
        params['status'] = status;
      }
      const where = conds.length > 0 ? 'WHERE ' + conds.join(' AND ') : '';
      const from = 'FROM expense_resolution er LEFT JOIN requisition r ON r.requisition_id = er.requisition_id ' + where;
      const countRows = await db.query('SELECT COUNT(*) AS "total" ' + from, params);
      const total = Number(countRows[0]['total']);
      const rows = await db.query(
        [
          'SELECT er.expense_resolution_id AS "expenseResolutionId",',
          'er.requisition_id AS "requisitionId",',
          'er.project_id AS "projectId",',
          'er.status AS "status",',
          'r.status AS "requisitionStatus"',
          from,
          'ORDER BY er.expense_resolution_id DESC LIMIT :limit OFFSET :offset',
        ].join(' '),
        { ...params, limit: limit, offset: page * limit },
      );
      return { items: rows, page: page, size: limit, total: total };
    });
  }

  @Post('/expense-resolutions/:expenseResolutionId/approve')
  @HttpCode(200)
  async approveExpenseResolution(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자', '임직원');
    const id = pathId(req.params['expenseResolutionId'], '결의서 ID');
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT status AS "status" FROM expense_resolution WHERE expense_resolution_id = CAST(:id AS bigint) FOR UPDATE',
        { id: id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'EXPENSE_RESOLUTION_NOT_FOUND', '결의서를 찾을 수 없습니다.');
      }
      if (rows[0]['status'] !== '결재대기') {
        throw new ApiError(409, 'APPROVAL_NOT_ALLOWED_STATUS', '결재대기 상태의 결의서만 승인할 수 있습니다.');
      }
      await db.execute(
        'UPDATE expense_resolution SET status = :newStatus, updated_at = now() WHERE expense_resolution_id = CAST(:id AS bigint)',
        { id: id, newStatus: '승인' },
      );
      await db.execute(
        [
          'INSERT INTO change_history (changer_id, target_type, target_id, change_type, changed_at, change_content, created_at, updated_at)',
          'VALUES (CAST(:userId AS bigint), :targetType, CAST(:id AS bigint), :changeType, now(), :content, now(), now())',
        ].join(' '),
        {
          userId: user.id,
          targetType: 'expense_resolution',
          id: id,
          changeType: '승인',
          content: '진행 상태: 결재대기 → 승인',
        },
      );
      return { status: '승인' };
    });
  }

  @Post('/requisitions/:requisitionId/approve')
  @HttpCode(200)
  async approveRequisition(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자', '임직원');
    const id = pathId(req.params['requisitionId'], '품의서 ID');
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT status AS "status" FROM requisition WHERE requisition_id = CAST(:id AS bigint) FOR UPDATE',
        { id: id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'REQUISITION_NOT_FOUND', '품의서를 찾을 수 없습니다.');
      }
      if (rows[0]['status'] !== '결재대기') {
        throw new ApiError(409, 'APPROVAL_NOT_ALLOWED_STATUS', '결재대기 상태의 품의서만 승인할 수 있습니다.');
      }
      await db.execute(
        'UPDATE requisition SET status = :newStatus, updated_at = now() WHERE requisition_id = CAST(:id AS bigint)',
        { id: id, newStatus: '승인' },
      );
      return { status: '승인' };
    });
  }
}

