import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Form,
  Field,
  Select,
  DateInput,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page, Column } from '../kit';

const STATUS_OPTIONS: [string, string][] = [
  ['기안', '기안'],
  ['결재대기', '결재대기'],
  ['승인', '승인'],
  ['보류', '보류'],
  ['반려', '반려'],
  ['회수', '회수'],
  ['재기안', '재기안'],
  ['완료', '완료'],
];

const PAGE_SIZE = 20;

interface Target {
  kind: 'resolution' | 'requisition';
  row: Row;
}

export default function FnSfr00403Page({ role, notify }: PageProps) {
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');
  const [projectId, setProjectId] = useState<number | string>('');
  const [status, setStatus] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [target, setTarget] = useState<Target | null>(null);

  const { data, error, loading, reload } = useData<Page>(
    () => call<Page>('GET', '/approval-items', role, undefined, { ...applied, page: page, size: PAGE_SIZE }),
    [applied, page],
  );

  function search() {
    setPage(0);
    setApplied({ fromDate: fromDate, toDate: toDate, projectId: projectId, status: status });
  }

  function reset() {
    setFromDate('');
    setToDate('');
    setProjectId('');
    setStatus('');
    setPage(0);
    setApplied({});
  }

  async function approve() {
    if (!target) {
      return;
    }
    if (target.kind === 'resolution') {
      await call('POST', '/expense-resolutions/' + String(target.row.expenseResolutionId) + '/approve', role, {});
      notify('결의서를 승인했습니다.');
    } else {
      await call('POST', '/requisitions/' + String(target.row.requisitionId) + '/approve', role, {});
      notify('품의서를 승인했습니다.');
    }
    setTarget(null);
    reload();
  }

  const columns: Column[] = [
    { key: 'expenseResolutionId', label: '결의서 ID' },
    {
      key: 'requisitionId',
      label: '품의서',
      render: (row) =>
        row.requisitionId ? <RefName table="requisition" role={role} value={row.requisitionId} /> : <span>-</span>,
    },
    {
      key: 'projectId',
      label: '프로젝트',
      render: (row) => <RefName table="project" role={role} value={row.projectId} />,
    },
    { key: 'status', label: '진행 상태', render: (row) => <Badge value={row.status} /> },
    {
      key: 'actions',
      label: '처리',
      render: (row) => (
        <span>
          {row.status === '결재대기' ? (
            <button className="ghost" onClick={() => setTarget({ kind: 'resolution', row: row })}>
              결의서 승인
            </button>
          ) : null}
          {row.requisitionId && row.requisitionStatus === '결재대기' ? (
            <button className="ghost" onClick={() => setTarget({ kind: 'requisition', row: row })}>
              품의서 승인
            </button>
          ) : null}
        </span>
      ),
    },
  ];

  const isResolution = target?.kind === 'resolution';

  return (
    <div className="doc">
      <section className="box">
        <h2>품의·결의 승인</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 시작일">
            <DateInput value={fromDate} onChange={setFromDate} />
          </Field>
          <Field label="조회 종료일">
            <DateInput value={toDate} onChange={setToDate} />
          </Field>
          <Field label="프로젝트">
            <LookupSelect table="project" role={role} value={projectId} onChange={setProjectId} />
          </Field>
          <Field label="진행 상태">
            <Select value={status} onChange={setStatus} options={STATUS_OPTIONS} />
          </Field>
        </Filters>
        {error ? <ErrorText text={error} /> : null}
        <Band total={data?.total} />
        <DataTable
          columns={columns}
          rows={data?.items ?? []}
          empty={loading ? '불러오는 중입니다.' : '조건에 맞는 품의·결의가 없습니다. 조회 조건을 바꿔 보세요.'}
        />
        <Pager page={page} size={PAGE_SIZE} total={data?.total ?? 0} onPage={setPage} />
      </section>
      {target ? (
        <Drawer title={isResolution ? '결의서 승인' : '품의서 승인'} onClose={() => setTarget(null)}>
          <Pairs
            items={[
              ['결의서 ID', String(target.row.expenseResolutionId)],
              ['프로젝트', <RefName table="project" role={role} value={target.row.projectId} />],
              ['현재 상태', <Badge value={isResolution ? target.row.status : target.row.requisitionStatus} />],
            ]}
          />
          <Form
            onSubmit={approve}
            submit="승인"
            note={isResolution ? '승인하면 결의서가 승인 상태가 되고 변경 이력이 남습니다.' : '승인하면 품의서가 승인 상태가 됩니다.'}
          >
            <p>이 건을 승인 처리할까요?</p>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
